   15	type Service struct{ S *store.Store }
   16	
   17	func Token() string { b := make([]byte, 16); rand.Read(b); return hex.EncodeToString(b) }
   18	
   19	// MaxSeconds bounds every seconds-valued input so that now+seconds never
   20	// leaves time.Duration's range (about 292 years).
   21	const MaxSeconds = math.MaxInt32
   22	
   23	// Backoff is the wait before retry attempt+1. It saturates at the queue's cap
   24	// (maxSeconds > 0) or at MaxSeconds instead of overflowing.
   25	func Backoff(kind string, base, attempt, maxSeconds int) time.Duration {
   26		limit := float64(MaxSeconds)
   27		if maxSeconds > 0 {
   28			limit = min(limit, float64(maxSeconds))
   29		}
   30		steps := float64(attempt)
   31		if kind != "linear" {
   32			steps = math.Exp2(float64(attempt - 1))
   33		}
   34		return time.Duration(min(float64(base)*steps, limit) * float64(time.Second))
   35	}
   36	
   37	const LeaseOrder = "priority DESC, created_at, id"
   38	
   39	func (j *Service) Lease(q, w int64, max int, now time.Time) ([]map[string]any, error) {
   40		tx, e := j.S.DB.Begin()
   41		if e != nil {
   42			return nil, e
   43		}
   44		defer tx.Rollback()
   45		var sec int
   46		var paused bool
   47		if e = tx.QueryRow(`SELECT lease_seconds,paused FROM queues WHERE id=$1`, q).Scan(&sec, &paused); e != nil {
   48			return nil, e
   49		}
   50		if paused {
   51			return []map[string]any{}, nil
   52		}
   53		var kinds pq.StringArray
   54		if e = tx.QueryRow(`SELECT kinds FROM workers WHERE id=$1`, w).Scan(&kinds); e != nil {
   55			return nil, e
   56		}
   57		rows, e := tx.Query(`SELECT id FROM jobs WHERE queue_id=$1 AND state='queued' AND kind=ANY($2) ORDER BY `+LeaseOrder+` LIMIT $3 FOR UPDATE SKIP LOCKED`, q, kinds, max)
   58		if e != nil {
   59			return nil, e
   60		}
   61		ids := []int64{}
   62		for rows.Next() {
   63			var id int64
   64			rows.Scan(&id)
   65			ids = append(ids, id)
   66		}
   67		rows.Close()
   68		out := []map[string]any{}
   69		for _, id := range ids {
   70			token := Token()
   71			var payload []byte
   72			var kind string
   73			var attempt int
   74			e = tx.QueryRow(`UPDATE jobs SET state='leased',leased_at=$5,event_at=$5,leased_by=$2,lease_token=$3,lease_expires_at=$4 WHERE id=$1 RETURNING kind,payload,attempts+1`, id, w, token, now.Add(time.Duration(sec)*time.Second), now).Scan(&kind, &payload, &attempt)
   75			if e != nil {
   76				return nil, e
   77			}
   78			out = append(out, map[string]any{"id": id, "kind": kind, "payload": json.RawMessage(payload), "attempt": attempt, "lease_token": token, "lease_expires_at": now.Add(time.Duration(sec) * time.Second)})
   79		}
   80		return out, tx.Commit()
   81	}
   82	func (j *Service) Notify(id int64, now time.Time) error {
   83		var url, secret, state, errtext string
   84		var result []byte
   85		e := j.S.DB.QueryRow(`SELECT q.webhook_url,q.webhook_secret,j.state,COALESCE(j.result,'null'),j.last_error FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id).Scan(&url, &secret, &state, &result, &errtext)
   86		if e != nil {
   87			return e
   88		}
   89		if url == "" {
   90			return nil
   91		}
   92		body, _ := json.Marshal(map[string]any{"job_id": id, "state": state, "result": json.RawMessage(result), "last_error": errtext})
   93		_, e = j.S.DB.Exec(`INSERT INTO webhook_outbox(job_id,url,secret,body,next_at,event_at,namespace_id,queue) SELECT $1,$2,$3,$4,$5,$5,j.namespace_id,q.name FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id, url, secret, string(body), now)
   94		return e
   95	}
   96	func (j *Service) Heartbeat(id int64, token string, seconds int, now time.Time) error {
   97		r, e := j.S.DB.Exec(`UPDATE jobs SET lease_expires_at=$3,event_at=$4 WHERE id=$1 AND lease_token=$2 AND state='leased'`, id, token, now.Add(time.Duration(seconds)*time.Second), now)
   98		return Changed(r, e)
   99	}
  100	func Changed(r sql.Result, e error) error {
  101		if e != nil {
  102			return e
  103		}
  104		n, e := r.RowsAffected()
  105		if e != nil {
  106			return e
  107		}
  108		if n == 0 {
  109			return fmt.Errorf("state conflict")
  110		}
  111		return nil
  112	}

