  1	package jobs
  2	
  3	import (
  4		"encoding/json"
  5		"time"
  6	)
  7	
  8	func (j *Service) Ack(id int64, token string, result any, now time.Time) error {
  9		b, _ := json.Marshal(result)
 10		r, e := j.S.DB.Exec(`UPDATE jobs SET state='succeeded',event_at=$3,result=$2,finished_at=$3,attempts=attempts+1 WHERE id=$1 AND state='leased' AND lease_token=$4`, id, string(b), now, token)
 11		if e = Changed(r, e); e != nil {
 12			return e
 13		}
 14		_, e = j.S.DB.Exec(`INSERT INTO attempts SELECT id,attempts,leased_by,leased_at,$2,'succeeded','' FROM jobs WHERE id=$1`, id, now)
 15		if e != nil {
 16			return e
 17		}
 18		return j.Notify(id, now)
 19	}
 20	package jobs
 21	
 22	import "time"
 23	
 24	func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
 25		tx, e := j.S.DB.Begin()
 26		if e != nil {
 27			return e
 28		}
 29		defer tx.Rollback()
 30		var attempts, max, base, cap int
 31		var kind string
 32		var worker int64
 33		e = tx.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base,COALESCE(q.backoff_max,0),j.leased_by FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1 AND j.state='leased' AND j.lease_token=$2 FOR UPDATE OF j`, id, token).Scan(&attempts, &max, &kind, &base, &cap, &worker)
 34		if e != nil {
 35			return e
 36		}
 37		state := "retry_wait"
 38		if !retry || attempts >= max {
 39			state = "dead"
 40		}
 41		wait := Backoff(kind, base, attempts, cap)
 42		if delay != nil {
 43			wait = time.Duration(*delay) * time.Second
 44		}
 45		_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$6,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
 46		if e != nil {
 47			return e
 48		}
 49		_, e = tx.Exec(`INSERT INTO attempts SELECT $1,$2,$3,leased_at,$4,'failed',$5 FROM jobs WHERE id=$1`, id, attempts, worker, now, message)
 50		if e != nil {
 51			return e
 52		}
 53		if e = tx.Commit(); e != nil {
 54			return e
 55		}
 56		if state == "dead" {
 57			return j.Notify(id, now)
 58		}
 59		return nil
 60	}
 61	package jobs
 62	
 63	import "time"
 64	
 65	func (j *Service) Expire(now time.Time) error {
 66	
 67		tx, e := j.S.DB.Begin()
 68		if e != nil {
 69			return e
 70		}
 71		defer tx.Rollback()
 72		rows, e := tx.Query(`SELECT id,attempts+1,max_attempts,leased_by FROM jobs WHERE state='leased' AND lease_expires_at <= $1 FOR UPDATE SKIP LOCKED`, now)
 73		if e != nil {
 74			return e
 75		}
 76		type expired struct {
 77			id, worker int64
 78			n, max     int
 79		}
 80		batch := []expired{}
 81		for rows.Next() {
 82			var r expired
 83			if e = rows.Scan(&r.id, &r.n, &r.max, &r.worker); e != nil {
 84				rows.Close()
 85				return e
 86			}
 87			batch = append(batch, r)
 88		}
 89		e = rows.Err()
 90		rows.Close()
 91		if e != nil {
 92			return e
 93		}
 94		dead := []int64{}
 95		for _, r := range batch {
 96			state := "queued"
 97			if r.n >= r.max {
 98				state = "dead"
 99				dead = append(dead, r.id)
100			}
101			_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$4,attempts=$3,last_error='lease expired',lease_token=NULL,leased_by=NULL,lease_expires_at=NULL,finished_at=CASE WHEN $2='dead' THEN $4::timestamptz ELSE NULL END WHERE id=$1`, r.id, state, r.n, now)
102			if e != nil {
103				return e
104			}
105			_, e = tx.Exec(`INSERT INTO attempts SELECT $1,$2,$3,leased_at,$4,'expired','lease expired' FROM jobs WHERE id=$1`, r.id, r.n, r.worker, now)
106			if e != nil {
107				return e
108			}
109		}
110		if e = tx.Commit(); e != nil {
111			return e
112		}
113		for _, id := range dead {
114			if e = j.Notify(id, now); e != nil {
115				return e
116			}
117		}
118		return nil
119	}
120	
121	func (j *Service) Promote(now time.Time) error {
122		_, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$1 WHERE state IN ('scheduled','retry_wait') AND run_at <= $1`, now)
123		return e
124	}
125	func (j *Service) Retain(now time.Time) error {
126		_, e := j.S.DB.Exec(`WITH removed AS (DELETE FROM jobs j USING queues q WHERE j.queue_id=q.id AND j.state IN ('succeeded','cancelled','dead') AND extract(epoch FROM $1::timestamptz - j.finished_at) / 3600 > q.retention_hours RETURNING j.*) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$1,'retained',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, now)
127		return e
128	}
129	package jobs
130	
131	import "time"
132	
133	func (j *Service) Cancel(id int64, now time.Time) error {
134		r, e := j.S.DB.Exec(`UPDATE jobs SET state='cancelled',event_at=$2,finished_at=$2 WHERE id=$1 AND state NOT IN ('succeeded','dead','cancelled')`, id, now)
135		if e = Changed(r, e); e != nil {
136			return e
137		}
138		return j.Notify(id, now)
139	}
140	func (j *Service) Retry(id int64, now time.Time) error {
141		r, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$2,attempts=0,run_at=$2,finished_at=NULL WHERE id=$1 AND state='dead'`, id, now)
142		return Changed(r, e)
143	}
144	package stats
145	
146	import (
147		"queuelet/internal/store"
148		"time"
149	)
150	
151	func Read(s *store.Store, where string, arg any, now time.Time) (map[string]any, error) {
152		rows, e := s.Rows(`SELECT state,count(*) AS count FROM jobs WHERE `+where+`=$1 GROUP BY state`, arg)
153		if e != nil {
154			return nil, e
155		}
156		m := map[string]any{"queued": int64(0), "leased": int64(0), "scheduled": int64(0), "retry_wait": int64(0), "succeeded": int64(0), "dead": int64(0), "cancelled": int64(0)}
157		for _, r := range rows {
158			m[r["state"].(string)] = r["count"]
159		}
160		var age float64
161		e = s.DB.QueryRow(`SELECT COALESCE(GREATEST(0,EXTRACT(EPOCH FROM ($2::timestamptz-min(GREATEST(created_at,run_at))))),0) FROM jobs WHERE `+where+`=$1 AND state='queued'`, arg, now).Scan(&age)
162		m["oldest_queued_age"] = age
163		var n int
164		e2 := s.DB.QueryRow(`SELECT count(*) FROM jobs WHERE `+where+`=$1 AND state='succeeded' AND finished_at >= $2`, arg, now.Add(-time.Hour)).Scan(&n)
165		m["throughput_last_hour"] = n
166		if e != nil {
167			return nil, e
168		}
169		return m, e2
170	}

