  1	package api
  2	
  3	import (
  4		"bytes"
  5		"context"
  6		"crypto/sha256"
  7		"database/sql"
  8		"encoding/hex"
  9		"encoding/json"
 10		"fmt"
 11		"io"
 12		"log"
 13		"net/http"
 14		"os"
 15		"queuelet/internal/clock"
 16		"queuelet/internal/jobs"
 17		"queuelet/internal/schedule"
 18		"queuelet/internal/store"
 19		"queuelet/internal/webhook"
 20		"reflect"
 21		"strconv"
 22		"strings"
 23		"sync/atomic"
 24		"time"
 25		"unicode/utf8"
 26	)
 27	
 28	type Server struct {
 29		Clock      clock.Clock
 30		S          *store.Store
 31		Jobs       *jobs.Service
 32		coreFailed atomic.Bool
 33		shipFailed atomic.Bool
 34	}
 35	type identity struct {
 36		Namespace int64
 37		Admin     bool
 38	}
 39	type authKey struct{}
 40	
 41	func New(s *store.Store) *Server     { return &Server{S: s, Jobs: &jobs.Service{S: s}} }
 42	func ident(r *http.Request) identity { return r.Context().Value(authKey{}).(identity) }
 43	func write(w http.ResponseWriter, status int, v any) {
 44		w.Header().Set("Content-Type", "application/json")
 45		w.WriteHeader(status)
 46		if v != nil {
 47			json.NewEncoder(w).Encode(v)
 48		}
 49	}
 50	func fail(w http.ResponseWriter, status int, code string, e any) {
 51		write(w, status, map[string]any{"error": map[string]any{"code": code, "message": fmt.Sprint(e)}})
 52	}
 53	func decode(w http.ResponseWriter, r *http.Request, v any) bool {
 54		body, e := io.ReadAll(http.MaxBytesReader(w, r.Body, 2<<20))
 55		if e == nil && !utf8.Valid(body) {
 56			e = fmt.Errorf("body is not valid UTF-8")
 57		}
 58		if e == nil {
 59			d := json.NewDecoder(bytes.NewReader(body))
 60			d.DisallowUnknownFields()
 61			d.UseNumber()
 62			if e = d.Decode(v); e == nil && d.Decode(&struct{}{}) != io.EOF {
 63				e = fmt.Errorf("unexpected data after the JSON object")
 64			}
 65		}
 66		if e == nil {
 67			var tree any
 68			json.Unmarshal(body, &tree)
 69			e = exactNames(tree, reflect.TypeOf(v))
 70		}
 71		if e != nil {
 72			fail(w, 400, "invalid_json", e)
 73			return false
 74		}
 75		return true
 76	}
 77	
 78	// exactNames rejects members that encoding/json matched to a field only
 79	// case-insensitively. Free-form members (payload, result) are not walked.
 80	func exactNames(v any, t reflect.Type) error {
 81		for t.Kind() == reflect.Pointer {
 82			t = t.Elem()
 83		}
 84		switch t.Kind() {
 85		case reflect.Slice:
 86			if items, ok := v.([]any); ok && t != reflect.TypeOf(json.RawMessage{}) {
 87				for _, item := range items {
 88					if e := exactNames(item, t.Elem()); e != nil {
 89						return e
 90					}
 91				}
 92			}
 93		case reflect.Struct:
 94			object, ok := v.(map[string]any)
 95			if !ok {
 96				return nil
 97			}
 98			fields := map[string]reflect.Type{}
 99			for i := 0; i < t.NumField(); i++ {
100				name, _, _ := strings.Cut(t.Field(i).Tag.Get("json"), ",")
101				fields[name] = t.Field(i).Type
102			}
103			for name, value := range object {
104				field, ok := fields[name]
105				if !ok {
106					return fmt.Errorf("json: unknown field %q", name)
107				}
108				if e := exactNames(value, field); e != nil {
109					return e
110				}
111			}
112		}
113		return nil
114	}
115	func num(r *http.Request, name string) int64 {
116		v, _ := strconv.ParseInt(r.PathValue(name), 10, 64)
117		return v
118	}
119	func (s *Server) Handler() http.Handler {
120		m := http.NewServeMux()
121		m.HandleFunc("GET /v1/jobs/{id}/events", s.events)
122		if os.Getenv("QUEUELET_TEST_CLOCK") == "1" {
123			m.HandleFunc("POST /admin/clock", s.clockControl)
124		}
125		m.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {
126			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
127			defer cancel()
128			if s.S.DB.PingContext(ctx) != nil || s.coreFailed.Load() || s.shipFailed.Load() {
129				write(w, 503, map[string]any{"status": "degraded"})
130				return
131			}
132			write(w, 200, map[string]any{"status": "ok"})
133		})
134		m.HandleFunc("GET /metrics", func(w http.ResponseWriter, r *http.Request) { fmt.Fprintln(w, "queuelet_up 1") })
135		m.HandleFunc("POST /v1/queues", s.createQueue)
136		m.HandleFunc("GET /v1/queues", s.listQueues)
137		m.HandleFunc("GET /v1/queues/{q}", s.getQueue)
138		m.HandleFunc("PATCH /v1/queues/{q}", s.patchQueue)
139		m.HandleFunc("DELETE /v1/queues/{q}", s.deleteQueue)
140		m.HandleFunc("POST /v1/queues/{q}/{verb}", s.queueVerb)
141		m.HandleFunc("GET /v1/queues/{q}/jobs", s.listJobs)
142		m.HandleFunc("GET /v1/queues/{q}/stats", s.queueStats)
143		m.HandleFunc("GET /v1/jobs/{id}", s.getJob)
144		m.HandleFunc("GET /v1/jobs/{id}/attempts", s.attempts)
145		m.HandleFunc("DELETE /v1/jobs/{id}", s.deleteJob)
146		m.HandleFunc("POST /v1/jobs/{id}/{verb}", s.jobVerb)
147		m.HandleFunc("POST /v1/workers", s.createWorker)
148		m.HandleFunc("DELETE /v1/workers/{id}", s.deleteWorker)
149		m.HandleFunc("POST /v1/schedules", s.createSchedule)
150		m.HandleFunc("GET /v1/schedules", s.listSchedules)
151		m.HandleFunc("GET /v1/schedules/{id}", s.getSchedule)
152		m.HandleFunc("PATCH /v1/schedules/{id}", s.patchSchedule)
153		m.HandleFunc("DELETE /v1/schedules/{id}", s.deleteSchedule)
154		m.HandleFunc("POST /v1/schedules/{id}/run", s.runSchedule)
155		m.HandleFunc("GET /v1/namespaces/{ns}/stats", s.namespaceStats)
156		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
157			if r.URL.Path == "/health" || r.URL.Path == "/metrics" {
158				m.ServeHTTP(w, r)
159				return
160			}
161			h := sha256.Sum256([]byte(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")))
162			var id identity
163			if e := s.S.DB.QueryRow(`SELECT namespace_id,admin FROM api_keys WHERE key_hash=$1`, hex.EncodeToString(h[:])).Scan(&id.Namespace, &id.Admin); e != nil {
164				if e == sql.ErrNoRows {
165					fail(w, 401, "unauthorized", "invalid API key")
166				} else {
167					fail(w, 503, "auth_unavailable", "authentication store unavailable")
168				}
169				return
170			}
171			m.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), authKey{}, id)))
172		})
173	}
174	func (s *Server) Loop(ctx context.Context) {
175		// Event console reads committed history; it never controls transitions.
176		go s.logEvents(ctx)
177		// A single shipper preserves delivery ordering without blocking lifecycle sweeps.
178		go func() {
179			t := time.NewTicker(time.Second)
180			defer t.Stop()
181			for {
182				select {
183				case <-ctx.Done():
184					return
185				case <-t.C:
186					now := s.Clock.Now()
187					e := webhook.Ship(s.S, now)
188					s.shipFailed.Store(e != nil)
189					if e != nil {
190						log.Printf("webhook task: %v", e)
191					}
192				}
193			}
194		}()
195		t := time.NewTicker(time.Second)
196		defer t.Stop()
197		for {
198			select {
199			case <-ctx.Done():
200				return
201			case <-t.C:
202				now := s.Clock.Now()
203				failed := false
204				for _, step := range []func(time.Time) error{s.Jobs.Promote, s.Jobs.Expire, func(t time.Time) error { return schedule.Fire(s.S, t) }, s.Jobs.Retain} {
205					if e := step(now); e != nil {
206						log.Printf("background task: %v", e)
207						failed = true
208					}
209				}
210				s.coreFailed.Store(failed)
211			}
212		}
213	}
214	func (s *Server) queue(r *http.Request) (map[string]any, error) {
215		name := r.PathValue("q")
216		if strings.ContainsAny(name, "/ ") {
217			return nil, fmt.Errorf("invalid queue path")
218		}
219		return s.S.One(`SELECT * FROM queues WHERE namespace_id=$1 AND name=$2`, ident(r).Namespace, name)
220	}
221	func (s *Server) queueOrError(w http.ResponseWriter, r *http.Request) (map[string]any, bool) {
222		q, e := s.queue(r)
223		if e != nil {
224			fail(w, 404, "queue_not_found", e)
225			return nil, false
226		}
227		return q, true
228	}
229	func output(w http.ResponseWriter, v any, e error) {
230		if e != nil {
231			fail(w, 500, "database_error", e)
232			return
233		}
234		write(w, 200, v)
235	}

