181	type JobInput struct {
182		Kind           string          `json:"kind"`
183		Payload        json.RawMessage `json:"payload"`
184		Priority       *int            `json:"priority"`
185		RunAt          *time.Time      `json:"run_at"`
186		DelaySeconds   *int            `json:"delay_seconds"`
187		MaxAttempts    *int            `json:"max_attempts"`
