input.command:
source tools/e04env.sh; T=$PWD/tools; {
ts; echo '--- R33b priority then FIFO (prediction: 9a,9b,5a,5b,0a)'
api POST /v1/queues -d '{"name":"e04k"}' >/dev/null
api POST /v1/queues/e04k/jobs:batch -d '{"jobs":[{"kind":"echo","payload":{"o":"5a"}},{"kind":"echo","payload":{"o":"0a"},"priority":0},{"kind":"echo","payload":{"o":"9a"},"priority":9},{"kind":"echo","payload":{"o":"5b"}},{"kind":"echo","payload":{"o":"9b"},"priority":9}]}'
for k in 1 2 3 4 5; do id=$(bash $T/lease1.sh e04k 3 | awk '{print $1}'); sql "select payload->>'o' from jobs where id=$id" | sed -n 2p; done | tr '\n' ' '; echo
} 2>&1 | tee $RES/p12-priority.txt

